for k, v in PLAIN.items():
    if k in T:
        old = T[k][0].count("%s") + T[k][0].count("%d")
        assert old == v[0].count("%s"), ("placeholder count changed", k)
    for s in v:
        assert s.count("%s") == v[0].count("%s"), ("language mismatch", k)
T.update(PLAIN)

out = {k: {"en": v[0], "fr": v[1], "rw": v[2]} for k, v in T.items()}
out["_meta"] = {"en": "French and Kinyarwanda are AI-assisted drafts pending native-speaker review."}
here = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(here, "translations.json"), "w", encoding="utf-8") as fh:
    json.dump(out, fh, ensure_ascii=False, indent=1)
print(len(T), "keys written")
